const STARTER=[{"id":"q001","sentence":"Mira stayed at home ---- she had a fever.","options":["because","so","but","when","if"],"answer":0,"level":1,"category":"Reason","explanation":"Because introduces the reason Mira stayed home.","pattern":"because + clause","hints":["Look for a reason.","The blank is followed by a full clause.","Use the conjunction that answers 'why?'."],"vocab":[],"wolf":false},{"id":"q002","sentence":"The lambs moved into the barn ---- the rain became heavy.","options":["because","so","but","when","if"],"answer":0,"level":1,"category":"Reason","explanation":"The heavy rain explains why the lambs moved into the barn.","pattern":"because + clause","hints":["The second clause gives a cause.","You need a conjunction before subject + verb.","Choose the word meaning 'for the reason that'."],"vocab":[],"wolf":false},{"id":"q003","sentence":"Rafi carried an umbrella ---- the sky looked dark.","options":["because","so","but","when","if"],"answer":0,"level":1,"category":"Reason","explanation":"The dark sky is the reason Rafi carried an umbrella.","pattern":"because + clause","hints":["Ask why Rafi carried it.","The words after the blank form a clause.","The answer directly introduces a reason."],"vocab":[],"wolf":false},{"id":"q004","sentence":"We opened the windows ---- the room was too warm.","options":["because","so","but","when","if"],"answer":0,"level":1,"category":"Reason","explanation":"The room being warm caused the action of opening the windows.","pattern":"because + clause","hints":["Cause or contrast?","The second part explains the first.","Use a reason conjunction."],"vocab":[],"wolf":false},{"id":"q005","sentence":"Nina whispered ---- the baby was sleeping.","options":["because","so","but","when","if"],"answer":0,"level":1,"category":"Reason","explanation":"The sleeping baby gives the reason Nina whispered.","pattern":"because + clause","hints":["Why did Nina whisper?","A full clause follows the blank.","Choose the reason connector."],"vocab":[],"wolf":false},{"id":"q006","sentence":"The path was muddy, ---- we walked slowly.","options":["because","so","but","when","if"],"answer":1,"level":1,"category":"Result","explanation":"So introduces the result of the muddy path.","pattern":"clause, so + clause","hints":["The second clause is a consequence.","Notice the comma before the blank.","Choose the connector meaning 'therefore' in simple coordination."],"vocab":[],"wolf":false},{"id":"q007","sentence":"I finished my chores early, ---- I had time to read.","options":["because","so","but","when","if"],"answer":1,"level":1,"category":"Result","explanation":"Having time to read is the result of finishing the chores early.","pattern":"clause, so + clause","hints":["What happened as a result?","The first clause causes the second.","Use the common coordinating result connector."],"vocab":[],"wolf":false},{"id":"q008","sentence":"The shop was closed, ---- we went somewhere else.","options":["because","so","but","when","if"],"answer":1,"level":1,"category":"Result","explanation":"Going elsewhere is the consequence of the shop being closed.","pattern":"clause, so + clause","hints":["Look for cause → result.","The result comes after the blank.","Choose 'so'."],"vocab":[],"wolf":false},{"id":"q009","sentence":"The bus was late, ---- Dimas called his teacher.","options":["because","so","but","when","if"],"answer":1,"level":1,"category":"Result","explanation":"Dimas's call results from the bus being late.","pattern":"clause, so + clause","hints":["Does the second event follow from the first?","The blank connects two independent clauses.","Use the result connector."],"vocab":[],"wolf":false},{"id":"q010","sentence":"The gate was locked, ---- we used the side entrance.","options":["because","so","but","when","if"],"answer":1,"level":1,"category":"Result","explanation":"Using the side entrance is the result of the locked gate.","pattern":"clause, so + clause","hints":["Identify the consequence.","The first fact explains the second action.","Choose 'so'."],"vocab":[],"wolf":false},{"id":"q011","sentence":"The book is short, ---- it is very informative.","options":["because","so","but","when","if"],"answer":2,"level":1,"category":"Contrast","explanation":"But links two contrasting facts: short yet informative.","pattern":"clause, but + clause","hints":["The ideas are different in an unexpected way.","You need a simple contrast conjunction.","Choose the word similar to 'yet'."],"vocab":[],"wolf":false},{"id":"q012","sentence":"Alya was tired, ---- she continued studying.","options":["because","so","but","when","if"],"answer":2,"level":1,"category":"Contrast","explanation":"But shows the contrast between being tired and continuing to study.","pattern":"clause, but + clause","hints":["Expectation versus reality.","She continued despite being tired.","Use a basic contrast connector."],"vocab":[],"wolf":false},{"id":"q013","sentence":"The room is small, ---- it feels comfortable.","options":["because","so","but","when","if"],"answer":2,"level":1,"category":"Contrast","explanation":"But contrasts small size with comfort.","pattern":"clause, but + clause","hints":["The second idea is positive despite the first.","This is not cause or result.","Choose 'but'."],"vocab":[],"wolf":false},{"id":"q014","sentence":"The task looked easy, ---- it took two hours.","options":["because","so","but","when","if"],"answer":2,"level":1,"category":"Contrast","explanation":"But marks an unexpected contrast between appearance and actual difficulty.","pattern":"clause, but + clause","hints":["The outcome differs from expectation.","Look for contrast.","Use 'but'."],"vocab":[],"wolf":false},{"id":"q015","sentence":"The sun was shining, ---- the air was cold.","options":["because","so","but","when","if"],"answer":2,"level":1,"category":"Contrast","explanation":"But contrasts sunshine with cold air.","pattern":"clause, but + clause","hints":["These two observations pull in different directions.","Not a cause-result relation.","Choose the coordinating contrast word."],"vocab":[],"wolf":false},{"id":"q016","sentence":"Call me ---- you arrive at the station.","options":["because","so","but","when","if"],"answer":3,"level":1,"category":"Time","explanation":"When introduces the time at which the call should happen.","pattern":"when + present clause","hints":["The sentence asks about timing.","The call happens at the moment of arrival.","Choose the time conjunction."],"vocab":[],"wolf":false},{"id":"q017","sentence":"The dog barked ---- it heard a noise outside.","options":["because","so","but","when","if"],"answer":3,"level":1,"category":"Time","explanation":"When marks the time/event that triggered the barking in this sentence.","pattern":"when + clause","hints":["Think about 'at the moment that'.","The blank introduces an event in time.","Choose 'when'."],"vocab":[],"wolf":false},{"id":"q018","sentence":"I usually make tea ---- I finish breakfast.","options":["because","so","but","when","if"],"answer":3,"level":1,"category":"Time","explanation":"When links the routine action to a recurring time/event.","pattern":"when + present clause","hints":["This describes a routine sequence.","The blank means 'at the time that'.","Use the time conjunction."],"vocab":[],"wolf":false},{"id":"q019","sentence":"The lights turn on automatically ---- it gets dark.","options":["because","so","but","when","if"],"answer":3,"level":1,"category":"Time","explanation":"When identifies the condition in time that triggers the automatic lights.","pattern":"when + present clause","hints":["This is a recurring trigger.","It happens every time darkness comes.","Choose 'when'."],"vocab":[],"wolf":false},{"id":"q020","sentence":"She smiles ---- her little brother tells a joke.","options":["because","so","but","when","if"],"answer":3,"level":1,"category":"Time","explanation":"When connects the smile to the moment the joke is told.","pattern":"when + clause","hints":["Focus on timing.","The blank can mean 'whenever'.","Choose 'when'."],"vocab":[],"wolf":false},{"id":"q021","sentence":"You can borrow my bicycle ---- you return it before sunset.","options":["because","so","but","when","if"],"answer":4,"level":1,"category":"Condition","explanation":"If introduces the condition for borrowing the bicycle.","pattern":"if + present, modal/main clause","hints":["There is a requirement.","The second clause sets a condition.","Choose the conditional conjunction."],"vocab":[],"wolf":false},{"id":"q022","sentence":"We will eat outside ---- the weather stays dry.","options":["because","so","but","when","if"],"answer":4,"level":1,"category":"Condition","explanation":"If introduces the condition needed for eating outside.","pattern":"if + present, will + verb","hints":["The plan depends on something.","The weather determines whether the plan happens.","Use 'if'."],"vocab":[],"wolf":false},{"id":"q023","sentence":"Take a jacket ---- you feel cold easily.","options":["because","so","but","when","if"],"answer":4,"level":1,"category":"Condition","explanation":"If introduces a condition that makes taking a jacket advisable.","pattern":"if + clause","hints":["This advice applies under a condition.","Ask 'under what circumstance?'.","Choose 'if'."],"vocab":[],"wolf":false},{"id":"q024","sentence":"Press this button ---- you need help.","options":["because","so","but","when","if"],"answer":4,"level":1,"category":"Condition","explanation":"If introduces the circumstance in which the button should be pressed.","pattern":"if + clause","hints":["This is an instruction for a possible situation.","The action depends on a condition.","Choose 'if'."],"vocab":[],"wolf":false},{"id":"q025","sentence":"I can explain it again ---- the instructions are unclear.","options":["because","so","but","when","if"],"answer":4,"level":1,"category":"Condition","explanation":"If introduces the condition that would make another explanation necessary.","pattern":"if + clause","hints":["The offer depends on a possible situation.","Not time, but condition.","Choose 'if'."],"vocab":[],"wolf":false},{"id":"q026","sentence":"---- the road was narrow, the driver remained calm.","options":["Although","Despite","So that","In order to","Unless"],"answer":0,"level":2,"category":"Concession","explanation":"Although correctly introduces a full clause expressing concession.","pattern":"although + subject + verb","hints":["The sentence presents an unexpected contrast.","A full clause follows the blank.","Use a concession conjunction, not a preposition."],"vocab":[],"wolf":false},{"id":"q027","sentence":"---- she was nervous, Maya gave a clear presentation.","options":["Although","Despite","So that","In order to","Unless"],"answer":0,"level":2,"category":"Concession","explanation":"Although introduces the clause 'she was nervous' and contrasts it with the successful presentation.","pattern":"although + clause","hints":["Nervousness would normally make presenting harder.","The blank is followed by subject + verb.","Choose 'Although'."],"vocab":[],"wolf":false},{"id":"q028","sentence":"---- the forecast predicted rain, the picnic continued.","options":["Although","Despite","So that","In order to","Unless"],"answer":0,"level":2,"category":"Concession","explanation":"Although links the forecast clause to the contrasting decision to continue.","pattern":"although + clause","hints":["Expectation is challenged.","After the blank comes a complete clause.","Use the clause-taking concession word."],"vocab":[],"wolf":false},{"id":"q029","sentence":"---- he had little experience, he learned the job quickly.","options":["Although","Despite","So that","In order to","Unless"],"answer":0,"level":2,"category":"Concession","explanation":"Although is followed by a clause and expresses a surprising contrast.","pattern":"although + clause","hints":["Little experience versus quick learning.","Check what structure follows the blank.","Choose 'Although'."],"vocab":[],"wolf":false},{"id":"q030","sentence":"---- the store was crowded, we found what we needed.","options":["Although","Despite","So that","In order to","Unless"],"answer":0,"level":2,"category":"Concession","explanation":"Although introduces the concessive clause 'the store was crowded'.","pattern":"although + clause","hints":["Crowds could make shopping difficult.","A full clause follows the blank.","Use 'Although'."],"vocab":[],"wolf":false},{"id":"q031","sentence":"---- the heavy rain, the match continued.","options":["Although","Despite","So that","In order to","Unless"],"answer":1,"level":2,"category":"Concession","explanation":"Despite is followed by the noun phrase 'the heavy rain'.","pattern":"despite + noun phrase","hints":["This is concession.","After the blank is a noun phrase, not a full clause.","Choose the preposition meaning 'in spite of'."],"vocab":[],"wolf":false},{"id":"q032","sentence":"---- feeling exhausted, Lina finished the report.","options":["Although","Despite","So that","In order to","Unless"],"answer":1,"level":2,"category":"Concession","explanation":"Despite can be followed by an -ing form such as 'feeling'.","pattern":"despite + -ing","hints":["She finished even though she was exhausted.","The blank is followed by an -ing form.","Use 'Despite'."],"vocab":[],"wolf":false},{"id":"q033","sentence":"---- the delay, everyone stayed patient.","options":["Although","Despite","So that","In order to","Unless"],"answer":1,"level":2,"category":"Concession","explanation":"Despite correctly precedes the noun phrase 'the delay'.","pattern":"despite + noun phrase","hints":["The delay did not change their patience.","A noun phrase follows.","Choose the concession preposition."],"vocab":[],"wolf":false},{"id":"q034","sentence":"---- his injury, Arman completed the walk.","options":["Although","Despite","So that","In order to","Unless"],"answer":1,"level":2,"category":"Concession","explanation":"Despite takes the noun phrase 'his injury'.","pattern":"despite + noun phrase","hints":["The injury makes the result surprising.","No subject + finite verb follows the blank.","Choose 'Despite'."],"vocab":[],"wolf":false},{"id":"q035","sentence":"---- working late, she woke up early.","options":["Although","Despite","So that","In order to","Unless"],"answer":1,"level":2,"category":"Concession","explanation":"Despite + -ing expresses concession before the main clause.","pattern":"despite + -ing","hints":["The two facts contrast.","The next word is an -ing form.","Use the preposition 'Despite'."],"vocab":[],"wolf":false},{"id":"q036","sentence":"Speak clearly ---- everyone can hear you.","options":["Although","Despite","So that","In order to","Unless"],"answer":2,"level":2,"category":"Purpose","explanation":"So that introduces a purpose clause with subject + modal verb.","pattern":"so that + subject + can/could/will/would","hints":["The second clause explains the purpose of speaking clearly.","A full clause follows the blank.","Choose the purpose expression used before subject + can."],"vocab":[],"wolf":false},{"id":"q037","sentence":"I wrote the address down ---- I would not forget it.","options":["Although","Despite","So that","In order to","Unless"],"answer":2,"level":2,"category":"Purpose","explanation":"So that introduces the intended result: not forgetting the address.","pattern":"so that + subject + modal","hints":["Why did the speaker write it down?","The blank is followed by 'I would'.","Use the purpose clause connector."],"vocab":[],"wolf":false},{"id":"q038","sentence":"They left early ---- they could avoid the traffic.","options":["Although","Despite","So that","In order to","Unless"],"answer":2,"level":2,"category":"Purpose","explanation":"So that + could expresses the purpose of leaving early.","pattern":"so that + subject + could","hints":["The second clause states a goal.","A subject and modal verb follow.","Choose 'So that'."],"vocab":[],"wolf":false},{"id":"q039","sentence":"The teacher repeated the rule ---- nobody would misunderstand it.","options":["Although","Despite","So that","In order to","Unless"],"answer":2,"level":2,"category":"Purpose","explanation":"So that introduces the purpose clause 'nobody would misunderstand it'.","pattern":"so that + clause","hints":["The repetition had an intended purpose.","The blank is followed by a complete clause.","Use 'So that'."],"vocab":[],"wolf":false},{"id":"q040","sentence":"We saved some water ---- the plants could survive the dry day.","options":["Although","Despite","So that","In order to","Unless"],"answer":2,"level":2,"category":"Purpose","explanation":"So that introduces a purpose clause containing 'the plants could survive'.","pattern":"so that + subject + could","hints":["Why was water saved?","Look for subject + could after the blank.","Use the purpose clause expression."],"vocab":[],"wolf":false},{"id":"q041","sentence":"Nadia took notes ---- remember the main points.","options":["Although","Despite","So that","In order to","Unless"],"answer":3,"level":2,"category":"Purpose","explanation":"In order to is followed by the base verb 'remember' and expresses purpose.","pattern":"in order to + base verb","hints":["The blank answers 'why did she take notes?'.","A base verb follows directly.","Choose the purpose phrase ending in 'to'."],"vocab":[],"wolf":false},{"id":"q042","sentence":"We moved the chairs ---- create more space.","options":["Although","Despite","So that","In order to","Unless"],"answer":3,"level":2,"category":"Purpose","explanation":"In order to + create states the purpose of moving the chairs.","pattern":"in order to + base verb","hints":["The second action is the goal.","The blank must be followed directly by a base verb.","Choose 'In order to'."],"vocab":[],"wolf":false},{"id":"q043","sentence":"He checked the map twice ---- avoid taking the wrong road.","options":["Although","Despite","So that","In order to","Unless"],"answer":3,"level":2,"category":"Purpose","explanation":"In order to is used before the infinitive 'avoid' to express purpose.","pattern":"in order to + base verb","hints":["Why did he check the map?","The next word is a base verb.","Use an infinitive purpose phrase."],"vocab":[],"wolf":false},{"id":"q044","sentence":"The team practised daily ---- improve its coordination.","options":["Although","Despite","So that","In order to","Unless"],"answer":3,"level":2,"category":"Purpose","explanation":"In order to + improve expresses the team's purpose.","pattern":"in order to + base verb","hints":["This is about intention, not result after the fact.","A base verb comes next.","Choose 'In order to'."],"vocab":[],"wolf":false},{"id":"q045","sentence":"She lowered her voice ---- avoid waking the child.","options":["Although","Despite","So that","In order to","Unless"],"answer":3,"level":2,"category":"Purpose","explanation":"In order to + avoid expresses why she lowered her voice.","pattern":"in order to + base verb","hints":["What was she trying to prevent?","The blank is followed by a base verb.","Use 'In order to'."],"vocab":[],"wolf":false},{"id":"q046","sentence":"You cannot enter the laboratory ---- you wear protective equipment.","options":["Although","Despite","So that","In order to","Unless"],"answer":4,"level":2,"category":"Condition","explanation":"Unless means 'if not': entry is impossible if protective equipment is not worn.","pattern":"unless + affirmative clause = if ... not","hints":["The sentence sets a necessary condition.","Think 'if you do not wear...'.","Choose 'Unless'."],"vocab":[],"wolf":false},{"id":"q047","sentence":"The plants will dry out ---- we water them regularly.","options":["Although","Despite","So that","In order to","Unless"],"answer":4,"level":2,"category":"Condition","explanation":"Unless means the plants will dry out if we do not water them.","pattern":"unless + clause","hints":["The negative condition is implied.","Rewrite it as 'if we do not...'.","Choose 'Unless'."],"vocab":[],"wolf":false},{"id":"q048","sentence":"Do not open the gate ---- the farmer gives permission.","options":["Although","Despite","So that","In order to","Unless"],"answer":4,"level":2,"category":"Condition","explanation":"Unless introduces the exception to the instruction.","pattern":"unless + clause","hints":["There is one condition under which opening is allowed.","The meaning is 'except if'.","Use 'Unless'."],"vocab":[],"wolf":false},{"id":"q049","sentence":"The event will remain outdoors ---- the weather becomes dangerous.","options":["Although","Despite","So that","In order to","Unless"],"answer":4,"level":2,"category":"Condition","explanation":"Unless means the event stays outdoors except if the weather becomes dangerous.","pattern":"unless + clause","hints":["Look for an exception.","It means 'except if'.","Choose 'Unless'."],"vocab":[],"wolf":false},{"id":"q050","sentence":"I will not change the schedule ---- there is a serious problem.","options":["Although","Despite","So that","In order to","Unless"],"answer":4,"level":2,"category":"Condition","explanation":"Unless introduces the only condition that would cause a schedule change.","pattern":"unless + clause","hints":["Only one circumstance changes the plan.","Think 'except if'.","Use 'Unless'."],"vocab":[],"wolf":false},{"id":"q051","sentence":"I have seen businesses moving out of the country ---- avoid paying taxes.","options":["in case","in view of","so as to","although","however"],"answer":2,"level":3,"category":"Purpose","explanation":"So as to is followed by the base verb 'avoid' and expresses purpose.","pattern":"so as to + base verb","hints":["Ask why the businesses are moving.","The blank is followed directly by the base verb 'avoid'.","Choose the purpose phrase equivalent to 'in order to'."],"vocab":[{"word":"avoid","id":"menghindari"}],"wolf":true},{"id":"q052","sentence":"She left a note on the table ---- remind us about the appointment.","options":["because of","whereas","so as to","provided that","in case"],"answer":2,"level":3,"category":"Purpose","explanation":"So as to + remind states the purpose of leaving the note.","pattern":"so as to + base verb","hints":["The note has an intended purpose.","A base verb follows the blank.","Use the formal purpose phrase."],"vocab":[],"wolf":false},{"id":"q053","sentence":"The hikers walked quietly ---- avoid disturbing the animals.","options":["because of","in case","whereas","so as to","provided that"],"answer":3,"level":3,"category":"Purpose","explanation":"So as to + avoid expresses the purpose of walking quietly.","pattern":"so as to + base verb","hints":["Why did they walk quietly?","The next word is a base verb.","Choose 'so as to'."],"vocab":[],"wolf":false},{"id":"q054","sentence":"He saved the document twice ---- reduce the risk of losing his work.","options":["although","so as to","in view of","however","in case"],"answer":1,"level":3,"category":"Purpose","explanation":"So as to + reduce expresses purpose.","pattern":"so as to + base verb","hints":["The action was intentional.","A base verb follows.","Use the purpose construction."],"vocab":[],"wolf":false},{"id":"q055","sentence":"They rearranged the shelves ---- make the entrance easier to use.","options":["so as to","because of","whereas","provided that","however"],"answer":0,"level":3,"category":"Purpose","explanation":"So as to + make expresses why the shelves were rearranged.","pattern":"so as to + base verb","hints":["The second action is the goal.","Look for an infinitive-type purpose phrase.","Choose 'so as to'."],"vocab":[],"wolf":false},{"id":"q056","sentence":"The flight was delayed ---- thick fog near the airport.","options":["because of","whereas","provided that","in case","so as to"],"answer":0,"level":3,"category":"Reason","explanation":"Because of is followed by the noun phrase 'thick fog' and gives the reason for the delay.","pattern":"because of + noun phrase","hints":["The phrase after the blank is a cause.","It is a noun phrase, not a full clause.","Use the reason preposition."],"vocab":[],"wolf":false},{"id":"q057","sentence":"The road was closed ---- a fallen tree.","options":["provided that","in case","because of","whereas","so as to"],"answer":2,"level":3,"category":"Reason","explanation":"Because of correctly introduces the noun phrase 'a fallen tree'.","pattern":"because of + noun phrase","hints":["What caused the closure?","The words after the blank form a noun phrase.","Choose 'because of'."],"vocab":[],"wolf":false},{"id":"q058","sentence":"Attendance was lower ---- the public transport strike.","options":["whereas","because of","so as to","in case","provided that"],"answer":1,"level":3,"category":"Reason","explanation":"Because of takes the noun phrase 'the public transport strike'.","pattern":"because of + noun phrase","hints":["The strike explains the lower attendance.","No finite verb follows the blank.","Use 'because of'."],"vocab":[],"wolf":false},{"id":"q059","sentence":"The crops grew slowly ---- the unusually cold spring.","options":["because of","whereas","provided that","in case","so as to"],"answer":0,"level":3,"category":"Reason","explanation":"Because of introduces the noun phrase giving the cause of slow growth.","pattern":"because of + noun phrase","hints":["Look for a cause.","A noun phrase follows.","Choose 'because of'."],"vocab":[],"wolf":false},{"id":"q060","sentence":"Several meetings were cancelled ---- the power outage.","options":["so as to","in case","provided that","because of","whereas"],"answer":3,"level":3,"category":"Reason","explanation":"Because of + the power outage gives the reason for the cancellations.","pattern":"because of + noun phrase","hints":["Why were meetings cancelled?","The blank comes before a noun phrase.","Use the reason preposition."],"vocab":[],"wolf":false},{"id":"q061","sentence":"My sister enjoys crowded cities, ---- I prefer quiet villages.","options":["whereas","because of","provided that","so as to","in case"],"answer":0,"level":3,"category":"Contrast","explanation":"Whereas directly contrasts the preferences of two subjects.","pattern":"clause, whereas + clause","hints":["Two people have opposite preferences.","The blank introduces another full clause.","Choose the formal contrast conjunction."],"vocab":[],"wolf":false},{"id":"q062","sentence":"The north field is dry, ---- the south field remains muddy.","options":["because of","in case","whereas","provided that","so as to"],"answer":2,"level":3,"category":"Contrast","explanation":"Whereas contrasts the conditions of the two fields.","pattern":"clause, whereas + clause","hints":["Compare two different conditions.","A full clause follows the blank.","Use 'whereas'."],"vocab":[],"wolf":false},{"id":"q063","sentence":"This model is inexpensive, ---- the newer model costs much more.","options":["provided that","whereas","so as to","because of","in case"],"answer":1,"level":3,"category":"Contrast","explanation":"Whereas contrasts the prices of the two models.","pattern":"clause, whereas + clause","hints":["The sentence compares two models.","The second clause presents the opposite situation.","Choose 'whereas'."],"vocab":[],"wolf":false},{"id":"q064","sentence":"Rina works best in the morning, ---- Dito is more productive at night.","options":["whereas","in case","because of","provided that","so as to"],"answer":0,"level":3,"category":"Contrast","explanation":"Whereas is appropriate for a direct comparison between Rina and Dito.","pattern":"clause, whereas + clause","hints":["This is a comparison with contrast.","Both sides are full clauses.","Use 'whereas'."],"vocab":[],"wolf":false},{"id":"q065","sentence":"The first solution saves time, ---- the second one reduces cost.","options":["because of","provided that","whereas","in case","so as to"],"answer":2,"level":3,"category":"Contrast","explanation":"Whereas contrasts two different advantages.","pattern":"clause, whereas + clause","hints":["The sentence contrasts two alternatives.","The blank joins two clauses.","Choose 'whereas'."],"vocab":[],"wolf":false},{"id":"q066","sentence":"You may use the meeting room ---- you leave it clean afterward.","options":["in case","provided that","because of","whereas","so as to"],"answer":1,"level":3,"category":"Condition","explanation":"Provided that means 'only if' and sets the condition for using the room.","pattern":"provided that + clause","hints":["Permission depends on a requirement.","The phrase means 'on condition that'.","Choose 'provided that'."],"vocab":[],"wolf":false},{"id":"q067","sentence":"The trip will go ahead ---- enough people register.","options":["whereas","because of","provided that","so as to","in case"],"answer":2,"level":3,"category":"Condition","explanation":"Provided that introduces the condition required for the trip to proceed.","pattern":"provided that + clause","hints":["The plan depends on registration numbers.","You need a formal condition connector.","Choose 'provided that'."],"vocab":[],"wolf":false},{"id":"q068","sentence":"We can finish today ---- the final data arrive before noon.","options":["provided that","because of","whereas","in case","so as to"],"answer":0,"level":3,"category":"Condition","explanation":"Provided that states the condition under which finishing today is possible.","pattern":"provided that + clause","hints":["One event must happen first.","The meaning is 'only if'.","Use 'provided that'."],"vocab":[],"wolf":false},{"id":"q069","sentence":"The warranty remains valid ---- the device is used as instructed.","options":["whereas","in case","provided that","because of","so as to"],"answer":2,"level":3,"category":"Condition","explanation":"Provided that introduces a condition for the warranty to remain valid.","pattern":"provided that + clause","hints":["Validity depends on correct use.","This is a formal condition.","Choose 'provided that'."],"vocab":[],"wolf":false},{"id":"q070","sentence":"You can join the workshop ---- there is still an empty seat.","options":["because of","provided that","so as to","whereas","in case"],"answer":1,"level":3,"category":"Condition","explanation":"Provided that states the condition for joining.","pattern":"provided that + clause","hints":["Joining depends on availability.","Think 'if and only if this requirement is satisfied'.","Use 'provided that'."],"vocab":[],"wolf":false},{"id":"q071","sentence":"Take a flashlight ---- the path becomes dark before you return.","options":["whereas","provided that","because of","in case","so as to"],"answer":3,"level":3,"category":"Precaution","explanation":"In case introduces a possible future situation that the flashlight is meant to prepare for.","pattern":"in case + clause","hints":["This is preparation for a possibility.","The flashlight is taken before the possible event.","Choose the precaution connector."],"vocab":[],"wolf":false},{"id":"q072","sentence":"I saved a copy of the file ---- the original became corrupted.","options":["in case","so as to","whereas","because of","provided that"],"answer":0,"level":3,"category":"Precaution","explanation":"In case introduces a possible problem that motivates a precaution.","pattern":"in case + past/present clause","hints":["The copy is a precaution.","The purpose is to be prepared for a possible problem, not to cause it.","Use 'in case'."],"vocab":[],"wolf":false},{"id":"q073","sentence":"Bring some cash ---- the card machine is not working.","options":["because of","whereas","in case","provided that","so as to"],"answer":2,"level":3,"category":"Precaution","explanation":"In case means 'as a precaution against the possibility that'.","pattern":"in case + clause","hints":["You are preparing for a possible situation.","The event may or may not happen.","Choose 'in case'."],"vocab":[],"wolf":false},{"id":"q074","sentence":"She packed an extra sweater ---- the evening turned cold.","options":["provided that","in case","because of","whereas","so as to"],"answer":1,"level":3,"category":"Precaution","explanation":"In case introduces the possible cold evening for which the sweater is a precaution.","pattern":"in case + clause","hints":["Why pack something extra?","The situation is only possible, not certain.","Use 'in case'."],"vocab":[],"wolf":false},{"id":"q075","sentence":"Keep the receipt ---- you need to return the item later.","options":["so as to","because of","provided that","in case","whereas"],"answer":3,"level":3,"category":"Precaution","explanation":"In case introduces a possible future need and explains the precaution of keeping the receipt.","pattern":"in case + clause","hints":["The receipt is kept for a possible future problem.","This is precaution, not purpose + infinitive.","Choose 'in case'."],"vocab":[],"wolf":false},{"id":"q076","sentence":"The evidence was incomplete; ----, the committee decided to continue the investigation.","options":["consequently","nevertheless","regardless of","even if","thereby"],"answer":1,"level":4,"category":"Contrast","explanation":"Nevertheless is a conjunctive adverb meaning 'in spite of that' and fits after the semicolon.","pattern":"clause; nevertheless, clause","hints":["The second decision happens despite the first fact.","The punctuation suggests a conjunctive adverb.","Choose the formal equivalent of 'even so'."],"vocab":[],"wolf":true},{"id":"q077","sentence":"The weather deteriorated rapidly; ----, the rescue team continued its search.","options":["nevertheless","consequently","thereby","even if","regardless of"],"answer":0,"level":4,"category":"Contrast","explanation":"Nevertheless shows that the search continued despite worsening weather.","pattern":"clause; nevertheless, clause","hints":["The second clause goes against expectation.","Look for a sentence adverb after a semicolon.","Use 'nevertheless'."],"vocab":[],"wolf":true},{"id":"q078","sentence":"The proposal was expensive; ----, the board approved it because of its long-term benefits.","options":["thereby","regardless of","consequently","nevertheless","even if"],"answer":3,"level":4,"category":"Contrast","explanation":"Nevertheless expresses concession: approval occurred despite the expense.","pattern":"clause; nevertheless, clause","hints":["Expense would normally discourage approval.","The relationship is concession, not result.","Choose 'nevertheless'."],"vocab":[],"wolf":true},{"id":"q079","sentence":"The first experiment failed; ----, the researchers did not abandon the hypothesis.","options":["consequently","nevertheless","even if","thereby","regardless of"],"answer":1,"level":4,"category":"Contrast","explanation":"Nevertheless means 'despite that' and connects the failed experiment to continued research.","pattern":"clause; nevertheless, clause","hints":["Failure did not produce the expected response.","This is an unexpected continuation.","Use 'nevertheless'."],"vocab":[],"wolf":true},{"id":"q080","sentence":"The route was longer than expected; ----, everyone reached the camp before dark.","options":["regardless of","thereby","nevertheless","consequently","even if"],"answer":2,"level":4,"category":"Contrast","explanation":"Nevertheless signals that reaching camp before dark occurred despite the longer route.","pattern":"clause; nevertheless, clause","hints":["Longer route versus successful arrival.","Not cause-result.","Choose 'nevertheless'."],"vocab":[],"wolf":true},{"id":"q081","sentence":"The main road was flooded; ----, all traffic was redirected through the eastern route.","options":["nevertheless","consequently","regardless of","thereby","even if"],"answer":1,"level":4,"category":"Result","explanation":"Consequently introduces the result of the flooding.","pattern":"clause; consequently, clause","hints":["The second clause follows as a result.","The punctuation suits a conjunctive adverb.","Choose the formal result word."],"vocab":[],"wolf":true},{"id":"q082","sentence":"The supplier missed the deadline; ----, production had to be rescheduled.","options":["regardless of","even if","consequently","nevertheless","thereby"],"answer":2,"level":4,"category":"Result","explanation":"Consequently means 'as a result' and links the missed deadline to rescheduling.","pattern":"clause; consequently, clause","hints":["Identify cause → effect.","You need a sentence-level result connector.","Use 'consequently'."],"vocab":[],"wolf":true},{"id":"q083","sentence":"Demand increased sharply; ----, the company added a second production shift.","options":["thereby","consequently","nevertheless","even if","regardless of"],"answer":1,"level":4,"category":"Result","explanation":"Consequently introduces the company's response as a result of increased demand.","pattern":"clause; consequently, clause","hints":["The second action is a consequence.","Look for a formal alternative to 'therefore'.","Choose 'consequently'."],"vocab":[],"wolf":true},{"id":"q084","sentence":"The safety inspection found several faults; ----, the building remained closed.","options":["consequently","regardless of","nevertheless","thereby","even if"],"answer":0,"level":4,"category":"Result","explanation":"Consequently links the faults to the decision to keep the building closed.","pattern":"clause; consequently, clause","hints":["Faults caused a later decision.","The relation is result.","Use 'consequently'."],"vocab":[],"wolf":true},{"id":"q085","sentence":"The temperature dropped below freezing; ----, several pipes burst overnight.","options":["nevertheless","thereby","regardless of","consequently","even if"],"answer":3,"level":4,"category":"Result","explanation":"Consequently expresses that the burst pipes were a result of the freezing temperature.","pattern":"clause; consequently, clause","hints":["One event caused another.","Choose a formal result adverb.","Use 'consequently'."],"vocab":[],"wolf":true},{"id":"q086","sentence":"The team will continue the survey ---- the weather conditions.","options":["nevertheless","regardless of","consequently","even if","thereby"],"answer":1,"level":4,"category":"Indifference","explanation":"Regardless of is followed by a noun phrase and means the weather conditions will not affect the decision.","pattern":"regardless of + noun phrase","hints":["The decision does not depend on the weather.","A noun phrase follows the blank.","Choose the expression meaning 'without being affected by'."],"vocab":[],"wolf":true},{"id":"q087","sentence":"All applications will be reviewed ---- the applicant's age.","options":["even if","thereby","regardless of","consequently","nevertheless"],"answer":2,"level":4,"category":"Indifference","explanation":"Regardless of + noun phrase means age will not influence whether an application is reviewed.","pattern":"regardless of + noun phrase","hints":["Age should not change the process.","The blank is followed by a noun phrase.","Use 'regardless of'."],"vocab":[],"wolf":true},{"id":"q088","sentence":"The alarm must be tested weekly ---- whether the building is occupied.","options":["regardless of","nevertheless","thereby","consequently","even if"],"answer":0,"level":4,"category":"Indifference","explanation":"Regardless of can be followed by a wh-clause such as 'whether the building is occupied'.","pattern":"regardless of + whether-clause","hints":["The rule applies in both cases.","The phrase after the blank begins with 'whether'.","Choose 'regardless of'."],"vocab":[],"wolf":true},{"id":"q089","sentence":"The policy applies to every employee ---- position or seniority.","options":["consequently","regardless of","even if","thereby","nevertheless"],"answer":1,"level":4,"category":"Indifference","explanation":"Regardless of + noun phrase states that position or seniority does not change the policy's application.","pattern":"regardless of + noun phrase","hints":["Status does not affect the rule.","A noun phrase follows.","Use 'regardless of'."],"vocab":[],"wolf":true},{"id":"q090","sentence":"She remained polite ---- the criticism she received.","options":["thereby","consequently","regardless of","even if","nevertheless"],"answer":2,"level":4,"category":"Indifference","explanation":"Regardless of + noun phrase indicates that the criticism did not change her polite behaviour.","pattern":"regardless of + noun phrase","hints":["Her behaviour stayed the same despite something.","The blank is followed by a noun phrase.","Choose 'regardless of'."],"vocab":[],"wolf":true},{"id":"q091","sentence":"I will attend the meeting ---- it lasts longer than expected.","options":["regardless of","even if","thereby","consequently","nevertheless"],"answer":1,"level":4,"category":"Condition-Concession","explanation":"Even if introduces a hypothetical condition that will not change the decision to attend.","pattern":"even if + clause","hints":["The decision remains the same under a possible condition.","A full clause follows the blank.","Choose the conditional concession phrase."],"vocab":[],"wolf":true},{"id":"q092","sentence":"The device should remain stable ---- the network connection becomes weak.","options":["thereby","nevertheless","even if","regardless of","consequently"],"answer":2,"level":4,"category":"Condition-Concession","explanation":"Even if introduces a possible adverse condition that should not change the result.","pattern":"even if + clause","hints":["Imagine a condition that does not alter the expected result.","The blank is followed by a full clause.","Use 'even if'."],"vocab":[],"wolf":true},{"id":"q093","sentence":"We will finish the route ---- we have to walk the final kilometre.","options":["consequently","even if","nevertheless","thereby","regardless of"],"answer":1,"level":4,"category":"Condition-Concession","explanation":"Even if means the possible need to walk will not change the plan to finish.","pattern":"even if + clause","hints":["The plan remains despite a possible difficulty.","The condition is hypothetical.","Choose 'even if'."],"vocab":[],"wolf":true},{"id":"q094","sentence":"Do not share the password ---- someone claims to be from technical support.","options":["even if","regardless of","thereby","consequently","nevertheless"],"answer":0,"level":4,"category":"Condition-Concession","explanation":"Even if introduces a possible claim that does not change the instruction.","pattern":"even if + clause","hints":["The warning remains valid under a possible circumstance.","A full clause follows.","Use 'even if'."],"vocab":[],"wolf":true},{"id":"q095","sentence":"The plants need regular watering ---- the weather feels cool.","options":["thereby","nevertheless","consequently","even if","regardless of"],"answer":3,"level":4,"category":"Condition-Concession","explanation":"Even if introduces a condition that does not remove the need for watering.","pattern":"even if + clause","hints":["Cool weather does not change the requirement.","The blank introduces a full hypothetical clause.","Choose 'even if'."],"vocab":[],"wolf":true},{"id":"q096","sentence":"The company replaced paper forms with a digital system, ---- reducing processing time.","options":["nevertheless","thereby","regardless of","even if","consequently"],"answer":1,"level":4,"category":"Means-Result","explanation":"Thereby + -ing means 'by doing that', showing how the change reduced processing time.","pattern":"thereby + -ing","hints":["The second phrase describes a result achieved by the first action.","The word after the blank is an -ing form.","Choose the adverb meaning 'by that means'."],"vocab":[],"wolf":true},{"id":"q097","sentence":"The new filter removes fine particles, ---- improving the quality of the water.","options":["thereby","consequently","even if","regardless of","nevertheless"],"answer":0,"level":4,"category":"Means-Result","explanation":"Thereby + improving means the removal of particles produces the improvement.","pattern":"thereby + -ing","hints":["One action directly brings about another result.","An -ing form follows the blank.","Use 'thereby'."],"vocab":[],"wolf":true},{"id":"q098","sentence":"The team automated several routine checks, ---- freeing more time for analysis.","options":["regardless of","thereby","nevertheless","consequently","even if"],"answer":1,"level":4,"category":"Means-Result","explanation":"Thereby + freeing shows that automation produced the additional available time.","pattern":"thereby + -ing","hints":["The first action creates the second outcome.","Look at the -ing form after the blank.","Choose 'thereby'."],"vocab":[],"wolf":true},{"id":"q099","sentence":"The redesign shortened the walking route, ---- making the facility easier to navigate.","options":["consequently","even if","thereby","nevertheless","regardless of"],"answer":2,"level":4,"category":"Means-Result","explanation":"Thereby + making expresses a result achieved through the redesign.","pattern":"thereby + -ing","hints":["The second phrase is a result produced by the redesign.","It begins with an -ing form.","Use 'thereby'."],"vocab":[],"wolf":true},{"id":"q100","sentence":"The update fixed the synchronization error, ---- preventing duplicate records.","options":["nevertheless","regardless of","consequently","thereby","even if"],"answer":3,"level":4,"category":"Means-Result","explanation":"Thereby + preventing means that fixing the error had the result of preventing duplicates.","pattern":"thereby + -ing","hints":["The first action causes the prevention described later.","An -ing form follows.","Choose the formal means-result adverb."],"vocab":[],"wolf":true}];
const KEY='sentencePasture.v1';
const PREF='sentencePasture.prefs';
const app=document.querySelector('#app'), modal=document.querySelector('#modal'), toast=document.querySelector('#toast');
let db=loadDB(), prefs=JSON.parse(localStorage.getItem(PREF)||'{"theme":"light","music":false,"sfx":true}');
let audioCtx=null, musicTimer=null, current=null, selected=null, checked=false, hintsUsed=0, practicePool=[], practiceIndex=0;
function loadDB(){try{let x=JSON.parse(localStorage.getItem(KEY)); if(x&&Array.isArray(x.questions)) return x}catch(e){} return {questions:structuredClone(STARTER),attempts:[],streak:0,lastDay:null}}
function save(){localStorage.setItem(KEY,JSON.stringify(db))}
function savePrefs(){localStorage.setItem(PREF,JSON.stringify(prefs))}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function showToast(t){toast.textContent=t;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1800)}
function beep(freq=480,d=.06){if(!prefs.sfx)return; try{audioCtx=audioCtx||new AudioContext();let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.frequency.value=freq;g.gain.value=.03;o.connect(g);g.connect(audioCtx.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+d);o.stop(audioCtx.currentTime+d)}catch(e){}}
function toggleMusic(){prefs.music=!prefs.music;savePrefs();syncControls(); if(prefs.music)startMusic(); else stopMusic()}
function startMusic(){try{audioCtx=audioCtx||new AudioContext();stopMusic(); let notes=[261.6,329.6,392,523.2]; let i=0; musicTimer=setInterval(()=>{if(!prefs.music)return;let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=notes[i++%notes.length];g.gain.value=.012;o.connect(g);g.connect(audioCtx.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.7);o.stop(audioCtx.currentTime+.7)},900)}catch(e){prefs.music=false}}
function stopMusic(){if(musicTimer)clearInterval(musicTimer);musicTimer=null}
function syncControls(){document.documentElement.dataset.theme=prefs.theme;document.querySelector('#themeBtn').textContent=prefs.theme==='light'?'☀':'☾';document.querySelector('#musicBtn').classList.toggle('active',prefs.music);document.querySelector('#sfxBtn').classList.toggle('active',prefs.sfx)}
document.querySelector('#themeBtn').onclick=()=>{prefs.theme=prefs.theme==='light'?'dark':'light';savePrefs();syncControls()};document.querySelector('#musicBtn').onclick=toggleMusic;document.querySelector('#sfxBtn').onclick=()=>{prefs.sfx=!prefs.sfx;savePrefs();syncControls();beep(600)};document.addEventListener('click',e=>{let b=e.target.closest('[data-go]');if(b)go(b.dataset.go)});syncControls();if(prefs.music)startMusic();
function go(v){if(v==='home')renderHome();if(v==='practice')startPractice(0);if(v==='bank')renderBank();if(v==='stats')renderStats();scrollTo(0,0)}
function accuracy(){if(!db.attempts.length)return 0;return Math.round(100*db.attempts.filter(a=>a.correct).length/db.attempts.length)}
function updateStreak(){let d=new Date().toISOString().slice(0,10);if(db.lastDay===d)return;if(db.lastDay){let prev=new Date(db.lastDay+'T00:00:00'),cur=new Date(d+'T00:00:00');db.streak=((cur-prev)/86400000===1)?db.streak+1:1}else db.streak=1;db.lastDay=d;save()}
function renderHome(){let acc=accuracy(),done=new Set(db.attempts.map(a=>a.id)).size;app.innerHTML=`<section class="hero"><div class="hero-card hero-copy"><div class="eyebrow">Complete the sentence</div><h1>Choose the bridge.<br><em>Outsmart the wolf.</em></h1><p>Train sentence logic through purpose, reason, contrast, result, condition and formal linking expressions. Every answer comes with a grammar frame and explanation.</p><div class="hero-actions"><button class="btn primary" onclick="startPractice(0)">Start mixed practice</button><button class="btn" onclick="renderBank()">Open question bank</button></div></div><div class="hero-card mascot-card"><div class="mascot">🐑</div><h3>Read the relationship.</h3><p>Do not guess from vocabulary alone. Ask what logical job the missing expression performs.</p><div class="mini-stats"><div class="mini-stat"><strong>${db.questions.length}</strong><span>questions</span></div><div class="mini-stat"><strong>${acc}%</strong><span>accuracy</span></div><div class="mini-stat"><strong>${db.streak}</strong><span>day streak</span></div></div><div class="wolf-peek">🐺</div></div></section><div class="section-head"><div><h2>Choose a trail</h2><p>Each level adds tighter grammar constraints and stronger distractors.</p></div></div><div class="mode-grid">${[1,2,3,4].map((l,i)=>`<button class="mode-card" onclick="startPractice(${l})"><div class="icon">${['🌱','🌾','🐑','🐺'][i]}</div><h3>${['Seedling','Meadow','Shepherd','Wolf Trail'][i]}</h3><p>${['Basic reason, result, contrast, time and condition.','Concession and purpose: although, despite, so that, in order to, unless.','Formal purpose, reason, contrast, conditions and precaution.','Conjunctive adverbs and high-risk grammar traps.'][i]}</p><span class="level-chip">25 starter questions</span></button>`).join('')}</div>`}
function startPractice(level=0){practicePool=db.questions.filter(q=>!level||q.level===level).sort(()=>Math.random()-.5);practiceIndex=0;nextQuestion()}
function nextQuestion(){if(!practicePool.length){renderHome();return} current=practicePool[practiceIndex%practicePool.length];selected=null;checked=false;hintsUsed=0;renderQuestion()}
function renderQuestion(){let q=current, letters='ABCDE';app.innerHTML=`<div class="section-head"><div><h2>${q.level===4?'🐺 Wolf Trail':'Sentence Trail'}</h2><p>Level ${q.level} · ${esc(q.category)} · Question ${practiceIndex+1}/${practicePool.length}</p></div><button class="btn ghost" onclick="renderHome()">Exit</button></div><div class="practice-layout"><section class="question-card"><div class="question-top"><span class="tag">${q.wolf?'🐺 WOLF QUESTION':'🐑 PRACTICE'}</span><span class="tag">${esc(q.category)}</span></div><div class="progress-line"><span style="width:${100*(practiceIndex+1)/practicePool.length}%"></span></div><div class="sentence">${esc(q.sentence).replace('----','<span class="blank">----</span>')}</div><div class="options">${q.options.map((o,i)=>`<button class="option ${selected===i?'selected':''} ${checked&&i===q.answer?'correct':''} ${checked&&selected===i&&i!==q.answer?'wrong':''}" onclick="pick(${i})" ${checked?'disabled':''}><span class="letter">${letters[i]}</span><span>${esc(o)}</span></button>`).join('')}</div><button class="btn ghost unknown" onclick="pick(-1)" ${checked?'disabled':''}>I don't know yet</button>${checked?`<div class="result-box"><h3>${selected===q.answer?'✓ Correct':'Correct answer: '+letters[q.answer]+') '+esc(q.options[q.answer])}</h3><p>${esc(q.explanation)}</p><div class="pattern">${esc(q.pattern)}</div></div>`:''}<div class="practice-actions">${checked?`<button class="btn primary" onclick="advance()">Next question →</button>`:`<button class="btn primary" onclick="checkAnswer()" ${selected===null?'disabled':''}>Check answer</button>`}<span>${checked?'':'Press a hint if you are stuck.'}</span></div></section><aside class="panel side-panel"><h3>💡 Hint ladder</h3><div class="hint-stack">${[0,1,2].map(i=>`<div class="hint-box"><b>Hint ${i+1}</b><br>${hintsUsed>i?esc(q.hints[i]):`<button class="btn ghost" onclick="useHint()">Reveal</button>`}</div>`).join('')}</div>${q.wolf?`<div class="wolf-note"><b>Wolf trap.</b> More than one option may look semantically plausible. Check the grammar frame after the blank.</div>`:''}</aside></div>`}
window.pick=i=>{if(checked)return;selected=i;beep(420);renderQuestion()};window.useHint=()=>{if(hintsUsed<3)hintsUsed++;renderQuestion()};window.checkAnswer=()=>{if(selected===null)return;checked=true;let correct=selected===current.answer;db.attempts.push({id:current.id,correct,level:current.level,category:current.category,hints:hintsUsed,ts:Date.now()});updateStreak();save();beep(correct?720:220,.1);renderQuestion()};window.advance=()=>{practiceIndex++;if(practiceIndex>=practicePool.length){showToast('Trail complete');renderStats()}else nextQuestion()};
function renderBank(){let levels=[1,2,3,4];app.innerHTML=`<div class="section-head"><div><h2>Question Bank</h2><p>Create, edit, duplicate and delete sentence-completion cards.</p></div><button class="btn primary" onclick="editQuestion()">+ Add question</button></div><div class="toolbar"><input id="search" placeholder="Search sentence or option…"><select id="levelFilter"><option value="0">All levels</option>${levels.map(l=>`<option value="${l}">Level ${l}</option>`).join('')}</select><button class="btn" onclick="exportData()">Export JSON</button><button class="btn" onclick="document.querySelector('#importFile').click()">Import</button><input id="importFile" type="file" accept="application/json" hidden></div><div id="bankList" class="bank-list" style="margin-top:16px"></div>`;let s=document.querySelector('#search'),f=document.querySelector('#levelFilter');let draw=()=>{let term=s.value.toLowerCase(),lv=+f.value;let arr=db.questions.filter(q=>(!lv||q.level===lv)&&(!term||(q.sentence+' '+q.options.join(' ')).toLowerCase().includes(term)));document.querySelector('#bankList').innerHTML=arr.map(q=>`<div class="bank-card"><div><h3>${esc(q.sentence)}</h3><p>Level ${q.level} · ${esc(q.category)} · Answer: <b>${esc(q.options[q.answer])}</b></p><span class="tag">${esc(q.pattern)}</span></div><div class="card-actions"><button class="icon-btn" onclick="editQuestion('${q.id}')">✎</button><button class="icon-btn" onclick="duplicateQuestion('${q.id}')">⧉</button><button class="icon-btn" onclick="deleteQuestion('${q.id}')">🗑</button></div></div>`).join('')||'<div class="empty">No matching questions.</div>'};s.oninput=f.onchange=draw;draw();document.querySelector('#importFile').onchange=importData}
window.editQuestion=id=>{let q=id?db.questions.find(x=>x.id===id):{id:'q'+Date.now(),sentence:'',options:['','','','',''],answer:0,level:1,category:'Reason',explanation:'',pattern:'',hints:['','',''],vocab:[],wolf:false};modal.classList.remove('hidden');modal.innerHTML=`<div class="modal"><h2>${id?'Edit':'Add'} question</h2><div class="form-grid"><label>Sentence <textarea id="mSentence" rows="3">${esc(q.sentence)}</textarea><small>Use exactly one ---- for the blank.</small></label><label>Level <select id="mLevel">${[1,2,3,4].map(l=>`<option ${q.level===l?'selected':''}>${l}</option>`).join('')}</select></label><label>Category <input id="mCategory" value="${esc(q.category)}"></label>${q.options.map((o,i)=>`<label>Option ${'ABCDE'[i]} <input class="mOpt" value="${esc(o)}"></label>`).join('')}<label>Correct answer <select id="mAnswer">${[0,1,2,3,4].map(i=>`<option value="${i}" ${q.answer===i?'selected':''}>${'ABCDE'[i]}</option>`).join('')}</select></label><label>Explanation <textarea id="mExplanation">${esc(q.explanation)}</textarea></label><label>Grammar frame <input id="mPattern" value="${esc(q.pattern)}"></label>${[0,1,2].map(i=>`<label>Hint ${i+1} <input class="mHint" value="${esc(q.hints[i]||'')}"></label>`).join('')}<label><span><input type="checkbox" id="mWolf" ${q.wolf?'checked':''}> Wolf question</span></label></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveQuestion('${q.id}')">Save</button></div></div>`}
window.closeModal=()=>modal.classList.add('hidden');modal.onclick=e=>{if(e.target===modal)closeModal()};
window.saveQuestion=id=>{let sentence=document.querySelector('#mSentence').value.trim();if((sentence.match(/----/g)||[]).length!==1)return showToast('Sentence needs exactly one ----');let opts=[...document.querySelectorAll('.mOpt')].map(x=>x.value.trim());if(opts.some(x=>!x))return showToast('Fill all five options');let q={id,sentence,options:opts,answer:+document.querySelector('#mAnswer').value,level:+document.querySelector('#mLevel').value,category:document.querySelector('#mCategory').value.trim(),explanation:document.querySelector('#mExplanation').value.trim(),pattern:document.querySelector('#mPattern').value.trim(),hints:[...document.querySelectorAll('.mHint')].map(x=>x.value.trim()),vocab:[],wolf:document.querySelector('#mWolf').checked};let i=db.questions.findIndex(x=>x.id===id);if(i>=0)db.questions[i]=q;else db.questions.push(q);save();closeModal();renderBank();showToast('Question saved')};
window.duplicateQuestion=id=>{let q=db.questions.find(x=>x.id===id);if(!q)return;let copy=structuredClone(q);copy.id='q'+Date.now();copy.sentence+=' (copy)';db.questions.push(copy);save();renderBank()};window.deleteQuestion=id=>{if(!confirm('Delete this question?'))return;db.questions=db.questions.filter(q=>q.id!==id);save();renderBank()};
window.exportData=()=>{let blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='sentence-pasture-backup.json';a.click();URL.revokeObjectURL(a.href)};function importData(e){let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{let x=JSON.parse(r.result);if(!Array.isArray(x.questions))throw 0;db=x;save();renderBank();showToast('Import complete')}catch(err){showToast('Invalid backup')}};r.readAsText(f)}
function renderStats(){let total=db.attempts.length,acc=accuracy();let unique=new Set(db.attempts.map(a=>a.id)).size;let byLevel=[1,2,3,4].map(l=>{let a=db.attempts.filter(x=>x.level===l);return {l,n:a.length,acc:a.length?Math.round(100*a.filter(x=>x.correct).length/a.length):0}});let cats={};db.attempts.forEach(a=>{cats[a.category]??={n:0,c:0};cats[a.category].n++;if(a.correct)cats[a.category].c++});app.innerHTML=`<div class="section-head"><div><h2>Progress</h2><p>Accuracy is descriptive, not a standardized proficiency score.</p></div><button class="btn" onclick="resetProgress()">Reset progress</button></div><div class="stats-grid"><div class="stat-card"><strong>${total}</strong><span>attempts</span></div><div class="stat-card"><strong>${acc}%</strong><span>overall accuracy</span></div><div class="stat-card"><strong>${unique}</strong><span>questions encountered</span></div><div class="stat-card"><strong>${db.streak}</strong><span>day streak</span></div></div><div class="panel" style="padding:22px;margin-top:18px"><h3>Accuracy by level</h3><div class="level-progress">${byLevel.map(x=>`<div class="level-row"><b>Level ${x.l}</b><div class="bar"><span style="width:${x.acc}%"></span></div><span>${x.acc}%</span></div>`).join('')}</div></div><div class="panel" style="padding:22px;margin-top:18px"><h3>Relationship types</h3>${Object.entries(cats).length?Object.entries(cats).sort((a,b)=>b[1].n-a[1].n).map(([k,v])=>`<p><b>${esc(k)}</b> · ${v.n} attempts · ${Math.round(100*v.c/v.n)}% correct</p>`).join(''):'<p>No attempts yet.</p>'}</div>`}
window.resetProgress=()=>{if(confirm('Reset attempts and streak?')){db.attempts=[];db.streak=0;db.lastDay=null;save();renderStats()}};
renderHome();